package io.knowledgebrain.notification;
import java.util.*;import java.time.*;import java.security.MessageDigest;
import io.knowledgebrain.contracts.collaboration.submissionfeedback.v1.*;
import io.knowledgebrain.contracts.collaboration.resubmissionrequest.v1.*;
import io.knowledgebrain.contracts.collaboration.submissiongrade.v1.*;
import io.knowledgebrain.contracts.collaboration.feedbackretraction.v1.*;
import io.knowledgebrain.contracts.collaboration.graderetraction.v1.*;
/** A deliberately content-free projection of the original immutable review event. */
final class ReviewSignal {
 static final List<String> TOPICS=List.of("collaboration.submission-feedback.v1","collaboration.resubmission-request.v1","collaboration.submission-grade.v1","collaboration.feedback-retraction.v1","collaboration.grade-retraction.v1");
 record Signal(UUID eventId,String payloadHash,String kind,UUID aggregateId,long sourceVersion,UUID groupId,UUID spaceId,UUID recipientId,UUID actorId,UUID studyId,UUID assignmentId,UUID submissionId,long submissionVersion,long occurredAt,String traceId) {}
 static IllegalArgumentException bad(){return new IllegalArgumentException("Invalid review signal");}
 static UUID id(String s){try{var v=UUID.fromString(s);if(v.version()!=7||v.variant()!=2||!v.toString().equals(s))throw bad();return v;}catch(RuntimeException e){throw bad();}}
 static String hash(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
 static Signal validate(Signal s){if(s==null)throw bad();for(UUID v:List.of(s.eventId(),s.aggregateId(),s.groupId(),s.spaceId(),s.recipientId(),s.actorId(),s.studyId(),s.assignmentId(),s.submissionId()))id(v.toString());if(!Set.of("FEEDBACK","RESUBMISSION_REQUESTED","RESUBMISSION_CANCELLED","RESUBMISSION_RESOLVED","GRADE","FEEDBACK_RETRACTED","FEEDBACK_RESTORED","GRADE_RETRACTED","GRADE_RESTORED").contains(s.kind())||s.sourceVersion()<1||s.submissionVersion()<1||s.occurredAt()<1||!s.payloadHash().matches("[0-9a-f]{64}")||!s.traceId().matches("[0-9a-f]{32}")||s.traceId().equals("0".repeat(32)))throw bad();return s;}
 static Signal decode(String topic,byte[] bytes){try{
  if(bytes==null||bytes.length>131072)throw bad();String event,kind,aggregate,group,space,author,actor,study,assignment,submission,trace,updated;long version,attempt,at;int ev;
  if(topic.equals(TOPICS.get(0))){var e=SubmissionFeedbackEnvelopeV1.parseFrom(bytes);var p=SubmissionFeedbackSnapshotV1.parseFrom(e.getPayload());if(!e.getProducer().equals("collaboration-service")||!e.getAggregateType().equals("SubmissionFeedback")||!e.getEventType().equals("SubmissionFeedbackRecorded")||!e.getAggregateId().equals(p.getFeedbackId())||!e.getSpaceId().equals(p.getSpaceId())||!e.getActorId().equals(p.getReviewerId())||!p.getAudience().equals("AUTHOR_AND_OWNER"))throw bad();event=e.getEventId();kind="FEEDBACK";aggregate=p.getFeedbackId();group=p.getGroupId();space=p.getSpaceId();author=p.getAuthorId();actor=p.getReviewerId();study=p.getStudyId();assignment=p.getAssignmentId();submission=p.getSubmissionId();version=p.getVersion();attempt=p.getSubmissionVersion();at=e.getOccurredAtEpochMillis();trace=e.getTraceId();updated=p.getUpdatedAt();ev=e.getEventVersion();}
  else if(topic.equals(TOPICS.get(1))){var e=ResubmissionRequestEnvelopeV1.parseFrom(bytes);var p=ResubmissionRequestSnapshotV1.parseFrom(e.getPayload());var types=Map.of("REQUESTED","ResubmissionRequested","CANCELLED","ResubmissionRequestCancelled","RESOLVED","ResubmissionRequestResolved");if(!e.getProducer().equals("collaboration-service")||!e.getAggregateType().equals("ResubmissionRequest")||!e.getEventType().equals(types.get(p.getState()))||!e.getAggregateId().equals(p.getRequestId())||!e.getSpaceId().equals(p.getSpaceId())||!e.getActorId().equals(p.getChangedBy())||!p.getAudience().equals("AUTHOR_AND_OWNER"))throw bad();event=e.getEventId();kind="RESUBMISSION_"+p.getState();aggregate=p.getRequestId();group=p.getGroupId();space=p.getSpaceId();author=p.getAuthorId();actor=p.getChangedBy();study=p.getStudyId();assignment=p.getAssignmentId();submission=p.getSubmissionId();version=p.getVersion();attempt=p.getSubmissionVersion();at=e.getOccurredAtEpochMillis();trace=e.getTraceId();updated=p.getUpdatedAt();ev=e.getEventVersion();}
  else if(topic.equals(TOPICS.get(2))){var e=SubmissionGradeEnvelopeV1.parseFrom(bytes);var p=SubmissionGradeSnapshotV1.parseFrom(e.getPayload());if(!e.getProducer().equals("collaboration-service")||!e.getAggregateType().equals("SubmissionGrade")||!e.getEventType().equals("SubmissionGradeRecorded")||!e.getAggregateId().equals(p.getGradeId())||!e.getSpaceId().equals(p.getSpaceId())||!e.getActorId().equals(p.getGraderId())||!p.getAudience().equals("AUTHOR_AND_OWNER")||Integer.toUnsignedLong(p.getScore())>100)throw bad();event=e.getEventId();kind="GRADE";aggregate=p.getGradeId();group=p.getGroupId();space=p.getSpaceId();author=p.getAuthorId();actor=p.getGraderId();study=p.getStudyId();assignment=p.getAssignmentId();submission=p.getSubmissionId();version=p.getVersion();attempt=p.getSubmissionVersion();at=e.getOccurredAtEpochMillis();trace=e.getTraceId();updated=p.getUpdatedAt();ev=e.getEventVersion();}
  else if(topic.equals(TOPICS.get(3))){var e=FeedbackRetractionEnvelopeV1.parseFrom(bytes);var p=FeedbackRetractionSnapshotV1.parseFrom(e.getPayload());id(p.getFeedbackId());var types=Map.of("RETRACTED","FeedbackRetracted","RESTORED","FeedbackRestored");if(!e.getProducer().equals("collaboration-service")||!e.getAggregateType().equals("FeedbackRetraction")||!e.getEventType().equals(types.get(p.getState()))||!e.getAggregateId().equals(p.getRetractionId())||!e.getSpaceId().equals(p.getSpaceId())||!e.getActorId().equals(p.getActorId())||!p.getAudience().equals("AUTHOR_AND_OWNER")||p.getFeedbackVersion()<1||p.getAssignmentVersion()<1)throw bad();event=e.getEventId();kind="FEEDBACK_"+p.getState();aggregate=p.getRetractionId();group=p.getGroupId();space=p.getSpaceId();author=p.getAuthorId();actor=p.getActorId();study=p.getStudyId();assignment=p.getAssignmentId();submission=p.getSubmissionId();version=p.getVersion();attempt=p.getSubmissionVersion();at=e.getOccurredAtEpochMillis();trace=e.getTraceId();updated=p.getUpdatedAt();ev=e.getEventVersion();}
  else if(topic.equals(TOPICS.get(4))){var e=GradeRetractionEnvelopeV1.parseFrom(bytes);var p=GradeRetractionSnapshotV1.parseFrom(e.getPayload());id(p.getGradeId());var types=Map.of("RETRACTED","GradeRetracted","RESTORED","GradeRestored");if(!e.getProducer().equals("collaboration-service")||!e.getAggregateType().equals("GradeRetraction")||!e.getEventType().equals(types.get(p.getState()))||!e.getAggregateId().equals(p.getRetractionId())||!e.getSpaceId().equals(p.getSpaceId())||!e.getActorId().equals(p.getActorId())||!p.getAudience().equals("AUTHOR_AND_OWNER")||p.getGradeVersion()<1||p.getAssignmentVersion()<1||p.getAuthorId().equals(p.getActorId()))throw bad();event=e.getEventId();kind="GRADE_"+p.getState();aggregate=p.getRetractionId();group=p.getGroupId();space=p.getSpaceId();author=p.getAuthorId();actor=p.getActorId();study=p.getStudyId();assignment=p.getAssignmentId();submission=p.getSubmissionId();version=p.getVersion();attempt=p.getSubmissionVersion();at=e.getOccurredAtEpochMillis();trace=e.getTraceId();updated=p.getUpdatedAt();ev=e.getEventVersion();}
  else throw bad();if(ev!=1||Instant.parse(updated).toEpochMilli()!=at)throw bad();return validate(new Signal(id(event),hash(bytes),kind,id(aggregate),version,id(group),id(space),id(author),id(actor),id(study),id(assignment),id(submission),attempt,at,trace));
 }catch(Exception e){throw bad();}}
 static void transport(String topic,String key,Map<String,String> headers,byte[] bytes){var s=decode(topic,bytes);String artifact=topic.substring("collaboration.".length(),topic.length()-3)+"-events";for(var e:Map.of("id",s.eventId().toString(),"trace_id",s.traceId(),"schema_group","collaboration","schema_artifact",artifact,"schema_version","1").entrySet())if(!e.getValue().equals(headers.get(e.getKey())))throw bad();if(!s.aggregateId().toString().equals(key))throw bad();}
}
